INSERT INTO quizzes (id, course_id, origin, slug, kind, title, description, first_lesson_id, last_lesson_id, published, created_at, updated_at) VALUES
  (1, 1, 'catalog', 'html-foundations', 'quiz', 'HTML Foundations', 'Lessons 1–6: structure, the page head, semantics, links, tables, and forms.', 1, 6, TRUE, '2026-07-01 10:00:00', '2026-07-01 10:00:00'),
  (2, 1, 'catalog', 'styling-and-boxes', 'quiz', 'Styling and Boxes', 'Lessons 7–12: selectors, the cascade, the box model, units, positioning, and flexbox.', 7, 12, TRUE, '2026-07-01 10:00:00', '2026-07-01 10:00:00'),
  (3, 1, 'catalog', 'layout-and-polish', 'quiz', 'Layout and Polish', 'Lessons 13–18: grid, responsive layouts and images, variables, transitions, and accessibility.', 13, 18, TRUE, '2026-07-01 10:00:00', '2026-07-01 10:00:00'),
  (4, 2, 'catalog', 'the-basics', 'quiz', 'The Basics', 'Lessons 1–7: variables, types, strings, operators, conditionals, and functions.', 19, 25, TRUE, '2026-07-02 10:00:00', '2026-07-02 10:00:00'),
  (5, 2, 'catalog', 'working-with-data', 'quiz', 'Working with Data', 'Lessons 8–14: scope, arrays, objects, destructuring, spread, and array methods.', 26, 32, TRUE, '2026-07-02 10:00:00', '2026-07-02 10:00:00'),
  (6, 2, 'catalog', 'browser-and-async', 'quiz', 'Browser and Async', 'Lessons 15–20: errors, the DOM, events, async code, and saving data.', 33, 38, TRUE, '2026-07-02 10:00:00', '2026-07-02 10:00:00'),
  (7, 3, 'catalog', 'python-basics', 'quiz', 'Python Basics', 'Lessons 1–6: printing, variables, strings, numbers, and user input.', 39, 44, TRUE, '2026-07-03 10:00:00', '2026-07-03 10:00:00'),
  (8, 3, 'catalog', 'logic-and-collections', 'quiz', 'Logic and Collections', 'Lessons 7–13: booleans, conditionals, lists, loops, comprehensions, and dictionaries.', 45, 51, TRUE, '2026-07-03 10:00:00', '2026-07-03 10:00:00'),
  (9, 3, 'catalog', 'functions-and-objects', 'quiz', 'Functions and Objects', 'Lessons 14–19: tuples, sets, functions, errors, files, and classes.', 52, 57, TRUE, '2026-07-03 10:00:00', '2026-07-03 10:00:00'),
  (10, 4, 'catalog', 'node-basics', 'quiz', 'Node Basics', 'Lessons 1–5: what Node is, running scripts, modules, npm, and the event loop.', 58, 62, TRUE, '2026-07-04 10:00:00', '2026-07-04 10:00:00'),
  (11, 4, 'catalog', 'files-and-servers', 'quiz', 'Files and Servers', 'Lessons 6–10: files, paths, environment variables, .env files, and your first HTTP server.', 63, 67, TRUE, '2026-07-04 10:00:00', '2026-07-04 10:00:00'),
  (12, 4, 'catalog', 'express-apis', 'quiz', 'Building with Express', 'Lessons 11–16: Express routes, middleware, static files, JSON APIs, and error handling.', 68, 73, TRUE, '2026-07-04 10:00:00', '2026-07-04 10:00:00'),
  (13, 5, 'catalog', 'database-basics', 'quiz', 'Database Basics', 'Lessons 1–6: tables, inserting rows, and reading data with SELECT, WHERE, IN, and BETWEEN.', 74, 79, TRUE, '2026-07-05 10:00:00', '2026-07-05 10:00:00'),
  (14, 5, 'catalog', 'shaping-data', 'quiz', 'Shaping Your Data', 'Lessons 7–12: NULL, sorting, changing rows and tables, aggregates, and keys.', 80, 85, TRUE, '2026-07-05 10:00:00', '2026-07-05 10:00:00'),
  (15, 5, 'catalog', 'relations-and-apps', 'quiz', 'Relations and Apps', 'Lessons 13–18: joins, subqueries, schema design, indexes, transactions, and connecting from your app.', 86, 91, TRUE, '2026-07-05 10:00:00', '2026-07-05 10:00:00'),
  (16, 6, 'catalog', 'components-and-jsx', 'quiz', 'Components and JSX', 'Lessons 1–7: components, JSX, props, children, lists, conditions, and events.', 92, 98, TRUE, '2026-07-06 10:00:00', '2026-07-06 10:00:00'),
  (17, 6, 'catalog', 'state-and-effects', 'quiz', 'State and Effects', 'Lessons 8–14: state, forms, lifting state, effects, fetching data, and refs.', 99, 105, TRUE, '2026-07-06 10:00:00', '2026-07-06 10:00:00'),
  (18, 6, 'catalog', 'building-real-apps', 'quiz', 'Building Real Apps', 'Lessons 15–20: custom hooks, context, routing, styling, performance, and deployment.', 106, 111, TRUE, '2026-07-06 10:00:00', '2026-07-06 10:00:00'),
  (19, 7, 'catalog', 'ml-foundations', 'quiz', 'ML Foundations', 'Lessons 1–6: what ML is, features and labels, data cleaning, splits, scaling, and linear regression.', 112, 117, TRUE, '2026-07-07 10:00:00', '2026-07-07 10:00:00'),
  (20, 7, 'catalog', 'training-and-models', 'quiz', 'Training and Models', 'Lessons 7–12: loss, gradient descent, learning rate, logistic regression, KNN, and decision trees.', 118, 123, TRUE, '2026-07-07 10:00:00', '2026-07-07 10:00:00'),
  (21, 7, 'catalog', 'better-models', 'quiz', 'Building Better Models', 'Lessons 13–17: random forests, overfitting, cross-validation, classifier metrics, and loss curves.', 124, 128, TRUE, '2026-07-07 10:00:00', '2026-07-07 10:00:00'),
  (22, 8, 'catalog', 'git-foundations', 'quiz', 'Git Foundations', 'Lessons 1–5: version control, setup, the three areas, commits, and checking your work.', 129, 133, TRUE, '2026-07-08 10:00:00', '2026-07-08 10:00:00'),
  (23, 8, 'catalog', 'undo-and-branch', 'quiz', 'Undoing and Branching', 'Lessons 6–10: .gitignore, undoing changes, branches, merging, and conflicts.', 134, 138, TRUE, '2026-07-08 10:00:00', '2026-07-08 10:00:00'),
  (24, 8, 'catalog', 'working-with-others', 'quiz', 'Working with Others', 'Lessons 11–15: remotes, pull requests, forks, rebasing, stashing, and tags.', 139, 143, TRUE, '2026-07-08 10:00:00', '2026-07-08 10:00:00'),
  (25, 9, 'catalog', 'complexity-and-searching', 'quiz', 'Complexity and Searching', 'Lessons 1–6: Big O, common complexities, lists, searching, and stacks.', 144, 149, TRUE, '2026-07-09 10:00:00', '2026-07-09 10:00:00'),
  (26, 9, 'catalog', 'structures-and-sorting', 'quiz', 'Structures and Sorting', 'Lessons 7–13: queues, hash tables, linked lists, recursion, and sorting.', 150, 156, TRUE, '2026-07-09 10:00:00', '2026-07-09 10:00:00'),
  (27, 9, 'catalog', 'patterns-trees-and-graphs', 'quiz', 'Patterns, Trees, and Graphs', 'Lessons 14–19: two pointers, sliding windows, trees, graphs, and heaps.', 157, 162, TRUE, '2026-07-09 10:00:00', '2026-07-09 10:00:00'),
  (28, 10, 'catalog', 'cloud-foundations', 'quiz', 'Cloud Foundations', 'Lessons 1–6: what the cloud is, service models, regions, virtual machines, storage, and managed databases.', 163, 168, TRUE, '2026-07-10 10:00:00', '2026-07-10 10:00:00'),
  (29, 10, 'catalog', 'networking-and-deploying', 'quiz', 'Networking and Deploying', 'Lessons 7–12: networking, production secrets, frontend builds, static sites, Node APIs, and Docker.', 169, 174, TRUE, '2026-07-10 10:00:00', '2026-07-10 10:00:00'),
  (30, 10, 'catalog', 'running-in-production', 'quiz', 'Running in Production', 'Lessons 13–18: Docker Compose, serverless, CI/CD, logs and monitoring, scaling, and cost and security.', 175, 180, TRUE, '2026-07-10 10:00:00', '2026-07-10 10:00:00');
INSERT INTO quiz_questions (id, quiz_id, position, prompt, explanation) VALUES
  (1, 1, 1, 'Which HTML element is used for the largest heading?', 'Headings run from h1 (largest) to h6 (smallest).'),
  (2, 1, 2, 'Which best describes HTML''s role?', 'HTML describes what content is, separate from how it looks.'),
  (3, 1, 3, 'What does the viewport meta tag do?', 'width=device-width makes phones render the page at their actual width, so responsive styles work.'),
  (4, 1, 4, 'Which semantic element is meant for a group of site navigation links?', '<nav> tells browsers and screen readers that its links are for navigating the site.'),
  (5, 1, 5, 'Why should every image have an alt attribute?', 'Screen readers read the alt text aloud, and it also shows if the image fails to load.'),
  (6, 1, 6, 'Which element creates a header cell in a table?', '<th> marks a header cell, while <td> is a regular data cell and <tr> is a row.'),
  (7, 1, 7, 'How do you link a <label> to its input?', 'A matching for and id pair connects them, so clicking the label focuses the field.'),
  (8, 2, 1, 'Which CSS selector targets every element with class="highlight"?', 'A leading dot targets elements by class attribute.'),
  (9, 2, 2, 'Two rules with equal specificity set different colors on the same element. Which one wins?', 'When specificity ties, the cascade applies the rule that appears last.'),
  (10, 2, 3, 'Which of these selectors is the most specific?', 'An id selector beats a class, and a class beats a tag.'),
  (11, 2, 4, 'In the box model, what is padding?', 'Padding sits between the content and the border, while margin sits outside the border.'),
  (12, 2, 5, 'What does box-sizing: border-box change?', 'With border-box, padding and border fit inside the width you set instead of adding to it.'),
  (13, 2, 6, 'Why is rem often better than px for font sizes?', 'rem is relative to the root font size, so text respects users who set a larger default.'),
  (14, 2, 7, 'An element with position: absolute is placed relative to what?', 'It anchors to the closest ancestor with a position set, or to the page if there isn''t one.'),
  (15, 2, 8, 'By default, what does display: flex do to an element''s direct children?', 'Flexbox arranges children in a row by default.'),
  (16, 3, 1, 'In CSS Grid, what does 1fr mean?', 'fr divides the remaining space, so three 1fr columns are always equal width.'),
  (17, 3, 2, 'What is a media query used for?', 'Media queries apply different rules depending on screen width.'),
  (18, 3, 3, 'What does max-width: 100% do for an image?', 'The image can shrink to fit its container but never spills out of it.'),
  (19, 3, 4, 'What does the srcset attribute let the browser do?', 'srcset lists several file sizes so smaller screens can download a smaller image.'),
  (20, 3, 5, 'How do you use a custom property named --accent?', 'The var() function reads the value of a custom property.'),
  (21, 3, 6, 'Where should you put the transition property for a hover effect?', 'On the base rule, the transition animates both when the hover starts and when it ends.'),
  (22, 3, 7, 'What''s a quick way to check your page''s keyboard accessibility?', 'Tabbing through reveals anything you can''t reach or whose focus you can''t see.'),
  (23, 4, 1, 'Which keyword should you use for a variable that will never be reassigned?', 'const declares a variable that can''t be reassigned, so default to it and use let only when the value needs to change.'),
  (24, 4, 2, 'What does typeof 21 return?', '21 is a number, so typeof reports "number".'),
  (25, 4, 3, 'What do template literals use to wrap their text?', 'Template literals are wrapped in backticks, which lets you insert values with ${}.'),
  (26, 4, 4, 'What does 5 === "5" evaluate to?', '=== compares both value and type without converting, and a number is not a string.'),
  (27, 4, 5, 'Which of these values is falsy?', 'The number 0 is falsy, while any non-empty string and any array are truthy.'),
  (28, 4, 6, 'If score is 72, what does score >= 60 ? "Pass" : "Fail" give you?', 'The condition is true, so the ternary returns the value before the colon.'),
  (29, 4, 7, 'Which keyword does a function use to send a result back to the caller?', 'return ends the function and hands its value back to whoever called it.'),
  (30, 5, 1, 'With const counter = makeCounter() from the closures lesson, what does the second call to counter() return?', 'The returned function remembers count between calls, so it goes 1 and then 2.'),
  (31, 5, 2, 'Given const courses = ["HTML", "CSS", "JavaScript"], what is courses[1]?', 'Arrays count from index 0, so index 1 is the second item.'),
  (32, 5, 3, 'How do you add a new city key to an existing student object?', 'Assigning to a new key with dot notation adds it to the object.'),
  (33, 5, 4, 'After const [first, second] = ["red", "green", "blue"], what is second?', 'Array destructuring unpacks by position, so second gets the item at index 1.'),
  (34, 5, 5, 'If user is { name: "Asha", age: 21 }, what is { ...user, age: 22 }?', 'Spread copies every key, and the later age: 22 overrides the copied value.'),
  (35, 5, 6, 'What does [45, 80, 92].filter((s) => s >= 60) return?', 'filter returns a new array containing only the items that pass the test.'),
  (36, 5, 7, 'What does [1, 2, 3].reduce((sum, n) => sum + n, 0) return?', 'reduce starts at 0 and adds each number in turn, ending with 6.'),
  (37, 5, 8, 'What does [45, 80, 92].find((s) => s >= 60) return?', 'find returns the first item that passes the test, not an array of all matches.'),
  (38, 6, 1, 'When does a finally block run?', 'finally always runs after try and catch, which makes it good for cleanup.'),
  (39, 6, 2, 'What is the difference between querySelector and querySelectorAll?', 'querySelector stops at the first matching element, while querySelectorAll returns all of them.'),
  (40, 6, 3, 'Which method runs a function every time a button is clicked?', 'addEventListener attaches a function that runs each time the event fires.'),
  (41, 6, 4, 'In what order does this log? console.log("A"); setTimeout(() => console.log("B"), 0); console.log("C");', 'setTimeout schedules its callback for later, even with a 0ms delay, so the rest of the code runs first.'),
  (42, 6, 5, 'Why wrap await calls in try/catch?', 'If the awaited promise rejects, catch lets you handle the error gracefully.'),
  (43, 6, 6, 'What does JSON.stringify do?', 'JSON.stringify converts a value into JSON text, and JSON.parse does the reverse.'),
  (44, 6, 7, 'What kind of values can localStorage store?', 'localStorage only stores strings, so objects must be stringified before saving.'),
  (45, 7, 1, 'What does a line starting with # do in Python?', 'Python skips everything after # on a line, so it is used for comments.'),
  (46, 7, 2, 'Which naming style does Python use for variables?', 'Python variable names use snake_case, like is_enrolled.'),
  (47, 7, 3, 'If course = "Python" and lessons = 12, what does print(f"{course} has {lessons} lessons.") show?', 'An f-string replaces each {name} with the value of that variable.'),
  (48, 7, 4, 'What does "  hi  ".strip() return?', 'strip() removes whitespace from both ends of a string.'),
  (49, 7, 5, 'What does "a,b,c".split(",") return?', 'split() breaks a string into a list at each separator.'),
  (50, 7, 6, 'What is the result of 7 // 2?', '// divides and rounds down to a whole number.'),
  (51, 7, 7, 'What type does input() always return?', 'input() always returns text, so you convert it with int() or float() for math.'),
  (52, 7, 8, 'What happens if int() is given text like "abc"?', 'int() cannot convert letters to a number, so it raises a ValueError.'),
  (53, 8, 1, 'What does True and False evaluate to?', 'and is only True when both sides are True.'),
  (54, 8, 2, 'Which of these values counts as False in a condition?', 'Empty values like [], "", and 0 are treated as False.'),
  (55, 8, 3, 'What does Python use to show which lines belong to an if branch?', 'Python uses indentation, typically four spaces, to group code into blocks.'),
  (56, 8, 4, 'Given fruits = ["apple", "mango", "orange"], what is fruits[-1]?', 'Negative indexes count from the end, so [-1] is the last item.'),
  (57, 8, 5, 'What does range(3) produce in a for loop?', 'range(3) starts at 0 and stops before 3.'),
  (58, 8, 6, 'What does continue do inside a loop?', 'continue skips the rest of the current pass and moves on to the next one.'),
  (59, 8, 7, 'What does [n * 2 for n in [1, 2, 3]] produce?', 'The comprehension doubles each item and collects the results in a new list.'),
  (60, 8, 8, 'How can you look up a dictionary key without an error if it might not exist?', 'get() returns None instead of raising an error when the key is missing.'),
  (61, 9, 1, 'What is the main difference between a tuple and a list?', 'Tuples are immutable, while lists can be changed.'),
  (62, 9, 2, 'What does a function return if it has no return statement?', 'A function without return gives back None.'),
  (63, 9, 3, 'In def total(*args), what type is args inside the function?', '*args collects the extra positional values into a tuple.'),
  (64, 9, 4, 'Why use keyword arguments like make_profile(age=22, name="Kiran")?', 'Passing arguments by name means you don''t need to follow the parameter order.'),
  (65, 9, 5, 'Which block runs when an error is raised inside try?', 'The matching except block catches the error and handles it.'),
  (66, 9, 6, 'What is the main benefit of opening a file with the with statement?', 'with opens the file safely and closes it when the block ends.'),
  (67, 9, 7, 'In a class method, what does self refer to?', 'self refers to the object being created or used, like rex in rex.bark().'),
  (68, 9, 8, 'Which method sets up each new object when it is created from a class?', '__init__ runs automatically to set up a new object''s data.'),
  (69, 10, 1, 'What does Node.js let you do?', 'Node runs JavaScript directly on your computer or a server, outside any browser.'),
  (70, 10, 2, 'Which of these does NOT exist in Node?', 'window and document only exist in browsers, not in Node.'),
  (71, 10, 3, 'How do you run a file called hello.js from the terminal?', 'The node command reads the file, runs it, and prints output to the terminal.'),
  (72, 10, 4, 'What does adding "type": "module" to package.json do?', 'With "type": "module", Node treats your files as modules that use import and export.'),
  (73, 10, 5, 'What does npm install express do?', 'npm install downloads the package and lists it under dependencies in package.json.'),
  (74, 10, 6, 'If node_modules gets messed up, what should you do?', 'node_modules can always be rebuilt from package.json with npm install.'),
  (75, 10, 7, 'A script logs "Start", sets a 1-second timer that logs "Timer", then logs "End". What prints?', 'The timer is handed off and the event loop runs its callback later, so the rest of the script keeps running first.'),
  (76, 11, 1, 'Why use the promise version of fs (node:fs/promises)?', 'The promise version lets you await file operations while Node keeps handling other work.'),
  (77, 11, 2, 'What does the node: prefix in "node:fs/promises" tell you?', 'The node: prefix marks a module that ships with Node rather than one installed from npm.'),
  (78, 11, 3, 'What is the best way to build a file path that works on every operating system?', 'path.join builds paths with the right separators for whatever system your code runs on.'),
  (79, 11, 4, 'What does path.extname("photo.png") return?', 'path.extname returns the file extension, including the dot.'),
  (80, 11, 5, 'Where should secrets like API keys be kept?', 'Environment variables keep secrets out of the code you commit to Git.'),
  (81, 11, 6, 'Which command starts app.js with the settings from a .env file loaded?', 'The --env-file flag loads the file''s values into process.env before your code runs.'),
  (82, 11, 7, 'Why should .env be listed in .gitignore?', 'Ignoring .env keeps secret values out of your Git history.'),
  (83, 11, 8, 'In http.createServer((req, res) => { ... }), what is res used for?', 'req describes the incoming request, and res is the object you use to send the response.'),
  (84, 12, 1, 'Why use Express instead of the plain http module?', 'Routing many URLs by hand with http gets messy, and Express makes it clean.'),
  (85, 12, 2, 'For the route /courses/:slug, where do you read the slug value?', 'Colon segments in the path become parameters on req.params.'),
  (86, 12, 3, 'For the URL /search?q=python, how do you read "python"?', 'req.query holds everything after the question mark.'),
  (87, 12, 4, 'What happens if your middleware forgets to call next()?', 'Without next() or a response, the request is never finished.'),
  (88, 12, 5, 'With app.use(express.static("public")), what URL serves public/style.css?', 'The folder name isn''t part of the URL, so files are served from the site root.'),
  (89, 12, 6, 'Which status code means a new resource was created?', '201 means created, which is what a successful POST that adds data returns.'),
  (90, 12, 7, 'Where should a catch-all 404 middleware go?', 'Express only reaches it when no earlier route matched the request.'),
  (91, 12, 8, 'How does Express recognize an error-handling middleware?', 'A middleware with four arguments is treated as an error handler.'),
  (92, 13, 1, 'In a relational database table, what does each row represent?', 'Each row is one record, while each column is one field.'),
  (93, 13, 2, 'What does adding UNIQUE to the email column do?', 'UNIQUE means no two students can sign up with the same address.'),
  (94, 13, 3, 'How should text values be written in an INSERT statement?', 'Text values go in single quotes, while numbers don''t need quotes.'),
  (95, 13, 4, 'What does SELECT * FROM students return?', 'The * means all columns, and without a WHERE every row is returned.'),
  (96, 13, 5, 'In the LIKE pattern ''%@example.com'', what does % mean?', 'In LIKE patterns, % matches any number of characters.'),
  (97, 13, 6, 'Which WHERE clause matches students from either Hyderabad or Chennai?', 'IN checks whether a value is one of a list, which is shorter than chaining ORs.'),
  (98, 13, 7, 'With BETWEEN ''2024-01-01'' AND ''2024-06-30'', are the two end dates included?', 'BETWEEN includes both ends of the range.'),
  (99, 13, 8, 'Why is it better to list columns instead of using * in real apps?', 'Listing only the columns you need is faster and clearer than *.'),
  (100, 14, 1, 'Why does WHERE city = NULL return no rows?', 'Comparing with NULL gives unknown, so you need IS NULL instead of = NULL.'),
  (101, 14, 2, 'What does COALESCE(city, ''Unknown'') return?', 'COALESCE swaps in a fallback value when the first value is NULL.'),
  (102, 14, 3, 'What does ORDER BY created_at DESC LIMIT 5 return?', 'DESC sorts newest first and LIMIT 5 keeps only the first five rows.'),
  (103, 14, 4, 'What happens if you run UPDATE students SET city = ''Mumbai''; with no WHERE?', 'Without a WHERE clause, UPDATE and DELETE affect every row.'),
  (104, 14, 5, 'Which statement adds a phone column to an existing students table?', 'ALTER TABLE changes an existing table''s structure without losing its rows.'),
  (105, 14, 6, 'What is the difference between WHERE and HAVING?', 'WHERE filters individual rows first, and HAVING filters the groups GROUP BY produces.'),
  (106, 14, 7, 'What does a foreign key do?', 'A foreign key references another table''s primary key, which is how tables relate.'),
  (107, 14, 8, 'What does SELECT city, COUNT(*) FROM students GROUP BY city return?', 'GROUP BY calculates the aggregate separately for each city.'),
  (108, 15, 1, 'How does LEFT JOIN differ from INNER JOIN?', 'LEFT JOIN keeps all rows from the first table and fills missing matches with NULL.'),
  (109, 15, 2, 'In a query that contains a subquery, which part runs first?', 'The inner query runs first and its result feeds the outer query.'),
  (110, 15, 3, 'What is the main goal of normalization?', 'Normalization avoids repeated data by giving each fact one home and linking to it with keys.'),
  (111, 15, 4, 'What is the trade-off of adding an index?', 'Indexes speed up searches but cost a little on writes and storage.'),
  (112, 15, 5, 'Which columns are worth indexing?', 'Index the columns you filter or join on often, not every column.'),
  (113, 15, 6, 'Inside a transaction, what does ROLLBACK do?', 'ROLLBACK cancels everything since BEGIN, so the changes all fail together.'),
  (114, 15, 7, 'Why pass user input as a $1 parameter instead of pasting it into the query text?', 'Parameters are filled in safely by the driver, so a malicious value can''t change the query.'),
  (115, 15, 8, 'Why use short aliases like s and c in a join?', 'Aliases are just short names that keep long joins readable.'),
  (116, 16, 1, 'What must a React component''s name start with?', 'React treats capitalized tags as components and lowercase tags as plain HTML elements.'),
  (117, 16, 2, 'In JSX, which attribute replaces HTML''s class?', 'class is a reserved word in JavaScript, so JSX uses className instead.'),
  (118, 16, 3, 'How do you pass the number 20 as a lessons prop?', 'Non-string values go in curly braces, while quotes would pass the text "20".'),
  (119, 16, 4, 'What does the children prop contain?', 'React passes anything nested inside a component''s tags to it as children.'),
  (120, 16, 5, 'Why does each item rendered with map need a key prop?', 'A unique, stable key lets React track which item is which when the list changes.'),
  (121, 16, 6, 'If unread is 0, what does {unread && <span>new</span>} render?', '&& returns the left side when it''s falsy, and React renders the number 0, so compare with > 0 instead.'),
  (122, 16, 7, 'Which line correctly runs handleClick when a button is clicked?', 'Pass the function itself; adding () would call it during render instead of on click.'),
  (123, 17, 1, 'What does useState(0) return?', 'useState returns a pair, usually destructured as const [count, setCount].'),
  (124, 17, 2, 'What is the correct way to add item to a todos state array?', 'Spreading into a new array gives React a fresh copy instead of mutating the old one.'),
  (125, 17, 3, 'What makes an input controlled?', 'A controlled input always shows the state value and reports every change back to it.'),
  (126, 17, 4, 'Why call event.preventDefault() in a form''s onSubmit handler?', 'By default a form submit reloads the page, which would wipe out your app''s state.'),
  (127, 17, 5, 'Two sibling components need the same state. Where should it live?', 'Lifting state to the shared parent lets it pass the value and a setter down to both.'),
  (128, 17, 6, 'When does a useEffect with an empty dependency array [] run?', 'With no dependencies to watch, the effect never needs to run again after the first time.'),
  (129, 17, 7, 'Why define an async function inside useEffect instead of making the effect itself async?', 'An effect may only return a cleanup function, but an async function always returns a promise.'),
  (130, 17, 8, 'What happens when you change a ref''s .current value?', 'Refs remember values between renders without triggering a re-render like state does.'),
  (131, 18, 1, 'What must a custom hook''s name start with?', 'Starting with use tells React and your linter that the function follows the rules of hooks.'),
  (132, 18, 2, 'Where is it safe to call a hook?', 'Hooks must be called in the same order on every render, so they belong at the top level.'),
  (133, 18, 3, 'Which hook reads the value provided by a context?', 'createContext makes the context, and useContext reads it from any component below the Provider.'),
  (134, 18, 4, 'With the route path "/course/:slug", how does the Course component read slug?', 'useParams returns an object with each : segment of the path, so const { slug } = useParams().'),
  (135, 18, 5, 'Why use React Router''s Link instead of a plain <a> tag for pages in your app?', 'Link updates the URL and swaps components in place, keeping your app''s state.'),
  (136, 18, 6, 'How is background-color written in a React inline style object?', 'Style objects use camelCase property names.'),
  (137, 18, 7, 'fullName is always first + " " + last. What''s the best way to get it?', 'Values you can compute from existing props or state don''t need their own state or an effect.'),
  (138, 18, 8, 'What does npm run build produce in a Vite project?', 'The build bundles and minifies your app into static files any static host can serve.'),
  (139, 19, 1, 'How does machine learning differ from traditional programming?', 'In machine learning you supply data plus answers, and the model learns the rules.'),
  (140, 19, 2, 'In a house price model, what is the price?', 'The label is the answer you want the model to predict, here the price.'),
  (141, 19, 3, 'What does df.isna().sum() tell you?', 'isna() marks missing values and sum() counts them per column.'),
  (142, 19, 4, 'Why do you hold back a test set?', 'A test set gives an honest measure of how the model does on new data.'),
  (143, 19, 5, 'When using StandardScaler, which data should you fit the scaler on?', 'Fitting on training data only prevents test-set information from leaking into training.'),
  (144, 19, 6, 'Why scale features like square feet and bedroom count?', 'Scaling puts features on a similar range so large-valued ones don''t dominate.'),
  (145, 19, 7, 'What does a linear regression coefficient tell you?', 'Each coefficient is the slope for its feature.'),
  (146, 20, 1, 'Why does mean squared error punish big mistakes more than small ones?', 'Squaring makes large errors grow much faster than small ones.'),
  (147, 20, 2, 'What does gradient descent do on each step?', 'The gradient shows which way the loss goes down, and the weights move that way.'),
  (148, 20, 3, 'Your loss suddenly shoots up to NaN. What should you try first?', 'A learning rate that''s too large makes training diverge.'),
  (149, 20, 4, 'What does logistic regression output before applying a threshold?', 'Logistic regression outputs a probability, and values over the threshold count as yes.'),
  (150, 20, 5, 'How does k-nearest neighbors classify a new point?', 'KNN looks at the nearest k examples and takes the most common class.'),
  (151, 20, 6, 'Why should you scale features before using KNN?', 'Distances are driven by the biggest numbers unless features are on a similar scale.'),
  (152, 20, 7, 'What does max_depth control in a decision tree?', 'Limiting depth keeps the tree from memorizing the training data.'),
  (153, 21, 1, 'What is a random forest?', 'A random forest is an ensemble of trees that vote together.'),
  (154, 21, 2, 'What is the classic sign of overfitting?', 'An overfit model does well on training data but badly on new data.'),
  (155, 21, 3, 'In Ridge regression, what happens when you raise alpha?', 'Higher alpha means a stronger regularization penalty and a simpler model.'),
  (156, 21, 4, 'Why use cross-validation instead of a single train/test split?', 'A single split can be lucky or unlucky, while an average across folds is more reliable.'),
  (157, 21, 5, 'What does recall measure?', 'Recall asks how many of the actual positives the model caught.'),
  (158, 21, 6, 'Why can accuracy alone be misleading?', 'With a rare class, a model can score high accuracy while missing most real positives.'),
  (159, 21, 7, 'On a loss curve, training loss keeps falling but validation loss starts rising. What does this mean?', 'Rising validation loss with falling training loss signals overfitting, which early stopping addresses.'),
  (160, 22, 1, 'What is the difference between Git and GitHub?', 'Git is the version control tool itself, and GitHub is one website that hosts copies of Git repositories.'),
  (161, 22, 2, 'Which command sets the name stamped on your commits for every project?', 'git config --global user.name sets your name once for all repositories on that computer.'),
  (162, 22, 3, 'What does git init create?', 'git init turns the folder into a repository by creating the .git folder where Git stores everything.'),
  (163, 22, 4, 'After git add index.html, where is the change?', 'git add stages the change, and it isn''t saved in the repository until you commit.'),
  (164, 22, 5, 'Which is the best commit message?', 'A good message is short, starts with a verb, and says what the change does.'),
  (165, 22, 6, 'Which command shows the exact lines you''ve changed but not yet staged?', 'git diff compares your working directory to the staging area, while --staged shows what''s already staged.'),
  (166, 22, 7, 'What does git log --oneline show?', 'git log lists past commits, and --oneline squeezes each one to its short id and message.'),
  (167, 23, 1, 'Which of these belongs in a .gitignore file?', 'Installed packages like node_modules/ can be reinstalled and shouldn''t be tracked.'),
  (168, 23, 2, 'You pushed a bad commit that teammates have already pulled. What''s the safe way to undo it?', 'git revert adds a new commit that reverses the old one, so it doesn''t rewrite shared history.'),
  (169, 23, 3, 'What does git reset --soft HEAD~1 do?', 'The soft reset removes the commit but leaves its changes in the staging area ready to recommit.'),
  (170, 23, 4, 'Which command creates a new branch and switches to it?', 'The -c flag tells git switch to create the branch before switching to it.'),
  (171, 23, 5, 'You want the add-navbar branch merged into main. Which branch should you be on when you run git merge add-navbar?', 'git merge brings another branch into the one you''re currently on.'),
  (172, 23, 6, 'What is a fast-forward merge?', 'If main has no new commits since you branched, Git simply moves main to your branch''s latest commit.'),
  (173, 23, 7, 'After editing a conflicted file to the version you want, what do you do next?', 'Staging the fixed file and committing tells Git the conflict is resolved and finishes the merge.'),
  (174, 24, 1, 'What is the default name for the remote you cloned from?', 'Git names the remote origin by default when you clone or when you follow the usual setup.'),
  (175, 24, 2, 'Which command downloads new commits from GitHub into your current branch?', 'git pull fetches new commits from the remote and brings them into your branch.'),
  (176, 24, 3, 'A reviewer asks for a change on your open pull request. What do you do?', 'Pushing new commits to the PR''s branch updates the pull request automatically.'),
  (177, 24, 4, 'In a forked project, what does the upstream remote usually point to?', 'You add upstream to track the original project so you can pull its latest changes.'),
  (178, 24, 5, 'When should you avoid rebasing?', 'Rebasing rewrites commits, which breaks things for anyone who already has the old versions.'),
  (179, 24, 6, 'You have unfinished changes and need to switch branches to fix something urgent. Which command shelves them?', 'git stash saves your uncommitted changes and cleans the folder, and git stash pop brings them back.'),
  (180, 24, 7, 'You created the tag v1.0.0 locally. How do you get it onto GitHub?', 'Tags aren''t pushed by default, so you push each one explicitly.'),
  (181, 25, 1, 'What does Big O notation describe?', 'Big O describes growth in work as input size increases, ignoring constants.'),
  (182, 25, 2, 'A loop that checks each item of an n-item list once is which complexity?', 'One step per item means the work grows in a straight line with n.'),
  (183, 25, 3, 'What complexity do two nested loops over the same list usually have?', 'For each of the n items the inner loop runs up to n times, giving O(n^2).'),
  (184, 25, 4, 'Which of these list operations is O(n)?', 'Inserting at the front forces every other item to shift one place right.'),
  (185, 25, 5, 'What is the worst-case time of linear search on n items?', 'If the target is last or missing, linear search checks every item.'),
  (186, 25, 6, 'What must be true of a list before you can use binary search on it?', 'Binary search relies on sorted order to know which half to throw away.'),
  (187, 25, 7, 'About how many steps does binary search need for 1,000,000 sorted items?', 'Halving a million items about 20 times gets down to one, since binary search is O(log n).'),
  (188, 25, 8, 'In what order does a stack remove items?', 'A stack''s pop() always removes the most recently pushed item.'),
  (189, 26, 1, 'Why use collections.deque instead of a list for a queue?', 'Removing from the front of a list shifts every item, but a deque does it in constant time.'),
  (190, 26, 2, 'What is the average time for checking x in my_set?', 'Sets are hash tables, so membership checks jump straight to where the value would be stored.'),
  (191, 26, 3, 'What does each node in a linked list hold?', 'Each node stores its value plus a link to the node after it.'),
  (192, 26, 4, 'How long does it take to reach the nth item of a linked list?', 'You have to walk the chain node by node from the head.'),
  (193, 26, 5, 'What stops a recursive function from calling itself forever?', 'The base case returns without making another recursive call.'),
  (194, 26, 6, 'What is the time complexity of selection sort?', 'Selection sort uses a loop inside a loop, so it is O(n^2).'),
  (195, 26, 7, 'What is the time complexity of merge sort?', 'There are about log n levels of splitting, and each level does O(n) merging work.'),
  (196, 26, 8, 'What can make quicksort slow down to O(n^2)?', 'Bad pivots split the list very unevenly, so the recursion goes n levels deep.'),
  (197, 27, 1, 'In the two-pointer pair-sum search on a sorted list, what do you do when the sum is too small?', 'Moving the left pointer right picks a larger number, which raises the sum.'),
  (198, 27, 2, 'What makes the sliding window technique fast?', 'Updating the window in one step turns an O(n * k) approach into O(n).'),
  (199, 27, 3, 'In a binary search tree, where do values smaller than a node go?', 'BSTs keep smaller values on the left and larger values on the right.'),
  (200, 27, 4, 'What happens if you insert already-sorted values into a plain BST?', 'Each new value goes to the same side, so the tree becomes one long chain.');
INSERT INTO quiz_questions (id, quiz_id, position, prompt, explanation) VALUES
  (201, 27, 5, 'Which structure does BFS use to visit nodes level by level?', 'A queue hands back nodes in the order they were found, which is level by level.'),
  (202, 27, 6, 'What does an in-order DFS of a binary search tree produce?', 'Visiting left, then the node, then right lists a BST''s values from smallest to largest.'),
  (203, 27, 7, 'Why does BFS on a graph need to track visited nodes?', 'Without a visited set, a cycle would send the search around the same nodes forever.'),
  (204, 27, 8, 'What does heapq.heappop() return?', 'heapq is a min-heap, so heappop() always removes and returns the smallest item.'),
  (205, 28, 1, 'What does "the cloud" mostly mean?', 'The cloud is compute, storage, and networking you rent from a provider instead of running your own hardware.'),
  (206, 28, 2, 'Which of these is an example of PaaS?', 'With PaaS you bring the code and the provider manages the runtime, OS, and hardware.'),
  (207, 28, 3, 'Why run copies of your app in two availability zones?', 'Zones are separate data centers with their own power and networking, so a problem in one leaves the others running.'),
  (208, 28, 4, 'On a virtual machine you rent, who is responsible for installing security updates?', 'A VM is like your own computer: patching the operating system is your job.'),
  (209, 28, 5, 'Where is the best place to keep images that users upload?', 'Buckets keep files safe even if the server is replaced, and serve them back by name.'),
  (210, 28, 6, 'What is block storage?', 'Block storage acts like a hard drive for a single machine, which suits databases and file systems.'),
  (211, 28, 7, 'What is the main benefit of a managed database?', 'A managed database takes the maintenance work off your hands while your code connects to it normally.'),
  (212, 29, 1, 'What does DNS do?', 'DNS looks up the IP address behind a friendly name like myapp.com.'),
  (213, 29, 2, 'Which port is normally used for HTTPS?', '443 is HTTPS, while 80 is plain HTTP and 22 is SSH.'),
  (214, 29, 3, 'What does a load balancer do?', 'A load balancer sits in front of your servers and shares requests between them.'),
  (215, 29, 4, 'Why should a config file throw an error at startup if a required variable is missing?', 'Failing fast makes a missing secret obvious right when you deploy.'),
  (216, 29, 5, 'Why must you never put secrets in VITE_ variables?', 'VITE_ values are baked into JavaScript files that every visitor downloads.'),
  (217, 29, 6, 'Refreshing /course/react on a deployed single-page app shows a 404. What fixes it?', 'The host must hand every path to index.html so the frontend router can take over.'),
  (218, 29, 7, 'Why should a deployed Node API listen on process.env.PORT?', 'Hosts pick the port and pass it in PORT, so a hard-coded port may never receive traffic.'),
  (219, 29, 8, 'Why does a Dockerfile copy package.json before copying the rest of the code?', 'The install step is only rerun when package.json changes, which speeds up rebuilds.'),
  (220, 30, 1, 'In a compose file with services api and db, how does the API reach the database?', 'Compose lets each service reach the others by its service name.'),
  (221, 30, 2, 'Why give the database service a named volume?', 'Without a volume, the database''s data disappears along with the container.'),
  (222, 30, 3, 'What best describes serverless functions?', 'Servers still exist, but the provider runs and scales them so you only deploy the function.'),
  (223, 30, 4, 'What is a cold start?', 'An idle function takes a moment to spin up before it can answer the first request.'),
  (224, 30, 5, 'In a GitHub Actions workflow, where should a deploy token live?', 'Repository secrets keep the token out of your code while the pipeline can still use it.'),
  (225, 30, 6, 'Why log one JSON line per event?', 'Structured logs let monitoring tools find and filter events by field.'),
  (226, 30, 7, 'What is horizontal scaling?', 'Horizontal scaling adds machines, while vertical scaling makes one machine bigger.'),
  (227, 30, 8, 'What does the principle of least privilege mean?', 'Limiting permissions means a leaked key can do as little damage as possible.');
