INSERT INTO course_reviews (id, course_id, student_id, rating, comment, created_at, updated_at) VALUES
  (1, 1, 16, 4, 'Accessibility lesson was an eye-opener. Wish there were videos for the later lessons too.', '2026-09-24 12:16:11', '2026-09-24 12:16:11'),
  (2, 1, 7, 4, 'Great structure. I''d love a longer project at the end that pulls the whole layout module together.', '2026-10-20 11:05:53', '2026-10-20 11:05:53'),
  (3, 1, 11, 5, 'The Flexbox and Grid lessons are the clearest explanation I''ve found anywhere.', '2026-09-01 20:55:19', '2026-09-01 20:55:19'),
  (4, 1, 15, 5, 'I''d never written HTML before and now I''ve built a small portfolio. The lesson videos for the first module made it click.', '2026-09-03 05:46:07', '2026-09-03 05:46:07'),
  (5, 2, 11, 5, 'Perfect pace for a beginner. The async/await lesson was worth the whole course.', '2026-10-07 15:33:41', '2026-10-07 15:33:41'),
  (6, 2, 16, 3, 'Helpful, though I wanted more practice before the quizzes.', '2026-09-18 05:08:43', '2026-09-18 05:08:43'),
  (7, 2, 10, 4, 'Solid fundamentals. The array methods section could use a few more exercises.', '2026-10-13 20:08:53', '2026-10-13 20:08:53'),
  (8, 2, 21, 4, 'Really liked the DOM lessons; I built a to-do list right after.', '2026-10-27 03:04:00', '2026-10-27 03:04:00'),
  (9, 2, 7, 5, 'Closures finally make sense. The examples are short and actually runnable.', '2026-09-22 09:02:57', '2026-09-22 09:02:57'),
  (10, 2, 20, 5, NULL, '2026-09-13 18:49:08', '2026-09-13 18:49:08'),
  (11, 2, 26, 3, NULL, '2026-10-20 15:40:48', '2026-10-20 15:40:48'),
  (12, 3, 22, 4, 'Used this to automate a spreadsheet task at work within a week.', '2026-10-06 13:45:42', '2026-10-06 13:45:42'),
  (13, 3, 7, 2, 'Too basic for me since I already knew some Java, but fine for complete beginners.', '2026-10-25 01:16:02', '2026-10-25 01:16:02'),
  (14, 3, 19, 5, 'Clear, friendly and well paced. The quizzes check exactly what the lessons teach.', '2026-10-27 04:45:00', '2026-10-27 04:45:00'),
  (15, 3, 21, 4, 'Great intro. The classes lesson felt short compared to the rest.', '2026-10-27 06:37:56', '2026-10-27 06:37:56'),
  (16, 3, 9, 5, 'My first programming course and I loved it. f-strings and list comprehensions are my new favourite things.', '2026-10-25 11:01:46', '2026-10-25 11:01:46'),
  (17, 3, 15, 3, NULL, '2026-09-21 18:40:02', '2026-09-21 18:40:02'),
  (18, 4, 10, 4, 'Good overview of Node. The .env lesson saved me from committing my keys.', '2026-09-19 17:40:37', '2026-09-19 17:40:37'),
  (19, 4, 26, 5, 'Went from zero to a working Express API. The middleware lesson is excellent.', '2026-10-27 04:57:18', '2026-10-27 04:57:18'),
  (20, 4, 24, 3, 'Event loop lesson needed a diagram; otherwise very good.', '2026-10-26 09:07:56', '2026-10-26 09:07:56'),
  (21, 4, 23, 4, 'Clear and practical, though I''d like a lesson on testing.', '2026-09-11 15:24:20', '2026-09-11 15:24:20'),
  (22, 4, 20, 5, NULL, '2026-09-23 12:10:56', '2026-09-23 12:10:56'),
  (23, 4, 17, 5, NULL, '2026-10-27 05:21:00', '2026-10-27 05:21:00'),
  (24, 5, 18, 4, 'Loved how every lesson builds on the same example tables.', '2026-10-26 23:42:32', '2026-10-26 23:42:32'),
  (25, 5, 16, 5, 'Joins explained properly at last. The schema design lesson is gold.', '2026-09-25 19:08:27', '2026-09-25 19:08:27'),
  (26, 5, 25, 4, 'Great course; the transactions lesson could go a bit deeper.', '2026-10-07 22:50:12', '2026-10-07 22:50:12'),
  (27, 6, 14, 4, 'Covers everything I needed to start a real app. The routing lesson is a bit brief.', '2026-09-18 08:06:49', '2026-09-18 08:06:49'),
  (28, 6, 12, 3, 'Good, but you really need the JavaScript course first.', '2026-10-27 04:37:08', '2026-10-27 04:37:08'),
  (29, 6, 13, 4, 'Great walkthrough of hooks. The context lesson was very useful for my project.', '2026-10-27 01:13:00', '2026-10-27 01:13:00'),
  (30, 7, 7, 5, 'Gradient descent explained without drowning in maths. Brilliant.', '2026-10-10 03:22:06', '2026-10-10 03:22:06'),
  (31, 7, 15, 3, 'Interesting but challenging; I had to rewatch the loss function lessons twice.', '2026-09-29 00:24:15', '2026-09-29 00:24:15'),
  (32, 7, 25, 4, 'Great intuition-first approach. Would like a full end-to-end project.', '2026-10-09 14:15:12', '2026-10-09 14:15:12'),
  (33, 7, 20, 4, 'The evaluation module is excellent — precision and recall finally make sense.', '2026-09-12 11:59:55', '2026-09-12 11:59:55'),
  (34, 7, 14, 4, NULL, '2026-10-01 22:00:38', '2026-10-01 22:00:38'),
  (35, 7, 19, 5, NULL, '2026-10-25 17:29:12', '2026-10-25 17:29:12'),
  (36, 8, 9, 4, 'Very good. Rebasing could use one more worked example.', '2026-10-25 08:55:21', '2026-10-25 08:55:21'),
  (37, 8, 8, 5, 'Short, practical lessons. The pull request lesson helped me make my first open-source contribution.', '2026-10-08 09:44:22', '2026-10-08 09:44:22'),
  (38, 8, 23, 5, 'I stopped being afraid of merge conflicts. Every developer should take this.', '2026-10-01 04:03:33', '2026-10-01 04:03:33'),
  (39, 9, 9, 4, 'Good balance of theory and code. I''d like more practice problems.', '2026-10-21 12:07:59', '2026-10-21 12:07:59'),
  (40, 9, 17, 5, 'Big O explained clearly, and the sliding window lesson helped me in an interview.', '2026-09-26 00:26:31', '2026-09-26 00:26:31'),
  (41, 9, 15, 4, 'Tough but rewarding. The tree traversal lessons are very well done.', '2026-10-01 00:09:55', '2026-10-01 00:09:55'),
  (42, 10, 22, 4, 'Useful cost and security tips I hadn''t seen elsewhere.', '2026-09-15 03:11:12', '2026-09-15 03:11:12'),
  (43, 10, 19, 4, 'Great overview of the cloud without vendor lock-in. CI/CD lesson was very practical.', '2026-09-24 19:27:50', '2026-09-24 19:27:50'),
  (44, 10, 24, 5, 'Finally deployed my Node API with Docker. The Compose lesson is spot on.', '2026-10-24 19:44:58', '2026-10-24 19:44:58');
